// ---- Fit ladder: a long name or role steps down in size before it may wrap. ----
// Each line tries its full size, then three smaller rungs; it only wraps (balanced) when even the
// smallest rung cannot hold it on one line. noacgTextOverflow() reports the lines that had to wrap
// so the operator panel can warn - the copy itself is never cut.
var LT_FIT_IDS = ['f0', 'f1'];
var LT_FIT_RUNGS = ['', 'lower-third-fit-1', 'lower-third-fit-2', 'lower-third-fit-3'];
var ltOverflow = [];
function ltSetRung(el, rung) {
  for (var i = 1; i < LT_FIT_RUNGS.length; i++) el.classList.remove(LT_FIT_RUNGS[i]);
  if (LT_FIT_RUNGS[rung]) el.classList.add(LT_FIT_RUNGS[rung]);
}
function fitPlacedText() {
  ltOverflow = [];
  for (var i = 0; i < LT_FIT_IDS.length; i++) {
    var el = document.getElementById(LT_FIT_IDS[i]);
    if (!el || !el.parentNode) continue;
    var mask = el.parentNode;
    var fitted = false;
    el.classList.add('lower-third-measure');
    for (var r = 0; r < LT_FIT_RUNGS.length; r++) {
      ltSetRung(el, r);
      if (el.offsetWidth <= mask.clientWidth + 1) { fitted = true; break; }
    }
    el.classList.remove('lower-third-measure');
    if (!fitted) ltOverflow.push(LT_FIT_IDS[i]);
  }
}
function noacgTextOverflow() { return ltOverflow.slice(); }
(function () {
  function boot() {
    fitPlacedText();
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(fitPlacedText);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
'''
